long long reverseNum(long long n) {
    long long ans = 0;
    while (n) { ans = ans * 10 + n % 10; n /= 10; }
    return ans;
}
bool isPalindrome(long long n) {
    if (n < 0) return false;
    return n == reverseNum(n);
}

