python.code:
def reverse_num(n: int) -> int:
    sign = -1 if n < 0 else 1
    n = abs(n)
    ans = 0
    while n:
        ans = ans * 10 + n % 10
        n //= 10
    return sign * ans

def is_palindrome(n: int) -> bool:
    return n >= 0 and n == reverse_num(n)

